    {/capture}
    {=og_include('blocks/menu-entry.latte', ['p' => ['href' => og_get($v_p, ['href']), 'className' => og_cnv(['gap-2 text-sm font-medium']), 'size' => 'sm', 'testid' => 'read'], 'children' => og_markup($c_6)])|noescape}
